from pathlib import Path
p = Path('crates/printer/src/util.rs')
s = p.read_text()
old = '''            matcher
                .replace_with_captures_at(
                    subject,
                    range.start,
                    caps,
                    dst,
                    |caps, dst| {
                        let start = dst.len();
                        caps.interpolate(
                            |name| matcher.capture_index(name),
                            subject,
                            replacement,
                            dst,
                        );
                        let end = dst.len();
                        matches.push(Match::new(start, end));
                        true
                    },
                )
                .map_err(io::Error::error_message)?;
'''
new = '''            let mut last_match = range.start;
            matcher
                .captures_iter_at(subject, range.start, caps, |caps| {
                    let m = caps.get(0).unwrap();
                    if is_multi_line && m.start() >= range.end {
                        return false;
                    }
                    dst.extend_from_slice(&subject[last_match..m.start()]);
                    last_match = m.end();
                    let start = dst.len();
                    caps.interpolate(
                        |name| matcher.capture_index(name),
                        subject,
                        replacement,
                        dst,
                    );
                    let end = dst.len();
                    matches.push(Match::new(start, end));
                    true
                })
                .map_err(io::Error::error_message)?;
            // The look-ahead region is for matching, not for printing.
            let end = if is_multi_line { range.end } else { subject.len() };
            dst.extend_from_slice(&subject[last_match..end]);
'''
assert s.count(old) == 1
p.write_text(s.replace(old, new))

p = Path('tests/multiline.rs')
s = p.read_text()
s += '''
rgtest!(replacement_named_capture, |dir: Dir, mut cmd: TestCommand| {
    dir.create("test", "# doc\\nfunc () {  # usage\\n    body\\n}\\n");
    cmd.args(&[
        "-N",
        "-U",
        "-r",
        "$usage",
        r"^(# .*\\n)*(func \\(\\) \\{)(  #(?P<usage> .+))?",
        "test",
    ]);
    eqnice!(" usage\\n", cmd.stdout());
});

rgtest!(replacement_match_boundaries, |dir: Dir, mut cmd: TestCommand| {
    dir.create(
        "test",
        "skip\\nprefix a\\nb a\\nb suffix\\ncontext\\nprefix a\\nb suffix\\nend\\n",
    );
    cmd.args(&["-N", "-U", "-r", "X", r"a\\nb", "test"]);
    eqnice!("prefix X X suffix\\nprefix X suffix\\n", cmd.stdout());
    cmd.arg("-o");
    eqnice!("X\\nX\\nX\\n", cmd.stdout());
});

rgtest!(replacement_look_around, |dir: Dir, mut cmd: TestCommand| {
    if !dir.is_pcre2() {
        return;
    }
    dir.create("test", "before\\na\\nb\\nc\\nend\\n");
    cmd.args(&[
        "-N",
        "-U",
        "-r",
        "X",
        r"(?<=before\\n)a\\nb(?=\\nc)",
        "test",
    ]);
    eqnice!("X\\n", cmd.stdout());
    cmd.arg("-C1");
    eqnice!("before\\nX\\nc\\n", cmd.stdout());
});

rgtest!(replacement_empty_at_end, |dir: Dir, mut cmd: TestCommand| {
    dir.create("test", "abc");
    cmd.args(&["-N", "-r", "X", "$", "test"]);
    eqnice!("abcX\\n", cmd.stdout());
    cmd.arg("-U");
    eqnice!("abcX\\n", cmd.stdout());
});
'''
p.write_text(s)

p = Path('crates/printer/src/standard.rs')
s = p.read_text()
old = '''    #[test]
    fn replacement_max_columns() {'''
new = '''    #[test]
    fn replacement_multi_line_named_capture() {
        let matcher = RegexMatcher::new(
            r"^(# .*\\n)*(func \\(\\) \\{)(  #(?P<usage> .+))?",
        )
        .unwrap();
        let mut printer = StandardBuilder::new()
            .replacement(Some(b"$usage".to_vec()))
            .build(NoColor::new(vec![]));
        SearcherBuilder::new()
            .multi_line(true)
            .build()
            .search_reader(
                &matcher,
                "# doc\\nfunc () {  # usage\\n    body\\n}\\n".as_bytes(),
                printer.sink(&matcher),
            )
            .unwrap();

        let got = printer_contents(&mut printer);
        assert_eq_printed!(" usage\\n", got);
    }

    #[test]
    fn replacement_max_columns() {'''
assert s.count(old) == 1
p.write_text(s.replace(old, new))

p = Path('CHANGELOG.md')
s = p.read_text()
old = 'Bug fixes:\n\n'
assert s.count(old) == 1
s = s.replace(old, old + '* Fix multiline replacements printing or replacing look-ahead text beyond the\n  matching lines.\n', 1)
p.write_text(s)
PY
