func () {  # usage
    body
}
' | target/debug/rg --no-config --color never -NU -r '$usage' '^(# .*
)*(func \(\) \{)(  #(?P<usage> .+))?'

cd /testbed && RUSTFLAGS=-Awarnings cargo build --features pcre2 --quiet && RUSTFLAGS=-Awarnings cargo test --package ripgrep --test integration --features pcre2 -- multiline:: regression::r1401 regression::r1412 regression::r1739 misc::replace && python3 - <<'PY'
import subprocess
content = '''# Compile requirements.txt files from all found or specified requirements.in files (compile).
# Use -h to include hashes, -u dep1,dep2... to upgrade specific dependencies, and -U to upgrade all.
pipc () {  # [-h] [-U|-u <pkgspec>[,<pkgspec>...]] [<reqs-in>...] [-- <pip-compile-arg>...]
    emulate -L zsh
    unset REPLY
    if [[ $1 == --help ]] { zpy $0; return }
    [[ $ZPY_PROCS ]] || return

    local gen_hashes upgrade upgrade_csv
    while [[ $1 == -[hUu] ]] {
        if [[ $1 == -h ]] { gen_hashes=--generate-hashes; shift   }
        if [[ $1 == -U ]] { upgrade=1;                    shift   }
        if [[ $1 == -u ]] { upgrade=1; upgrade_csv=$2;    shift 2 }
    }
}
'''
pattern = r'^(?P<predoc>\n?(# .*\n)*)(alias (?P<aname>pipc)="[^"]+"|(?P<fname>pipc) \(\) \{)(  #(?P<usage> .+))?'
expected = ' [-h] [-U|-u <pkgspec>[,<pkgspec>...]] [<reqs-in>...] [-- <pip-compile-arg>...]\n'
for engine in ([], ['--pcre2']):
    command = ['target/debug/rg', '--no-config', '--color', 'never', '-NU', '-r', '$usage', *engine, pattern]
    result = subprocess.run(command, input=content, text=True, capture_output=True, check=True)
    assert result.stdout == expected, repr(result.stdout)
print('Original report: exact expected output with both regex engines.')
PY

